<template>
	<view class="invite-page">
		<view class="invite-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="header-row">
				<view class="back-button" @click="goBack"><view class="back-arrow" /></view>
				<text class="header-title">邀请好友</text>
				<view class="header-space" />
			</view>
		</view>
		<scroll-view class="invite-scroll" scroll-y :show-scrollbar="false" :style="{ height: scrollHeight + 'px' }">
			<view class="invite-hero">
				<view class="hero-cloud cloud-one" /><view class="hero-cloud cloud-two" />
				<text class="hero-spark spark-one">✦</text><text class="hero-spark spark-two">✦</text>
				<view class="gift-stack"><view class="gift-lid" /><view class="gift-box"><view class="gift-ribbon" /></view><view class="gift-bow bow-left" /><view class="gift-bow bow-right" /></view>
				<text class="hero-title">邀请好友</text><text class="hero-title hero-title-accent">领取更多权益</text>
				<text class="hero-copy">和朋友一起记录，让温暖的相遇更多一点</text>
			</view>

			<view class="invite-card">
				<view class="invite-stats"><view><text>已邀请人数</text><text class="count-value">{{ inviteCount }}</text></view><view class="stats-divider" /><view><text>累计获得</text><text class="count-value diamond-value">{{ rewardDiamonds }} 钻</text></view></view>
				<view v-if="codeLoading || invitationCodeUrl" class="poster-panel" @click="previewInvitationCode" @longpress="saveInvitationCode">
					<view v-if="codeLoading" class="code-state"><text class="code-loading-dot" /><text>正在生成专属二维码</text></view>
					<image v-else class="invitation-code" :src="invitationCodeUrl" mode="aspectFit" />
				</view>
				<text v-if="invitationCodeUrl" class="save-hint">点击预览，长按保存专属二维码</text>
				<button class="share-button" open-type="share" :disabled="!inviterId" hover-class="share-button-hover">{{ inviterId ? '分享至好友' : '正在准备邀请信息' }}</button>
			</view>

			<view class="reward-section">
				<view class="section-title-row"><text class="section-title">邀请同行礼</text><text class="title-gift">🎁</text></view>
				<view class="rule-list">
					<text class="rule-item"><text class="rule-dot">•</text>每成功邀请 1 位新好友加入，你将获得 {{ rewardPerInvite }} 钻石。</text>
					<text class="rule-item"><text class="rule-dot">•</text>好友通过你的分享链接首次登录后，奖励自动到账。</text>
					<text class="rule-item"><text class="rule-dot">•</text>邀请好友一起捡纸条、写纸条，发现更多同频的心事。</text>
					<text class="rule-item"><text class="rule-dot">•</text>完成资料、发布动态和纸条、回复纸条，均可通过成长任务获得钻石。</text>
					<text class="rule-item"><text class="rule-dot">•</text>钻石可用于收取纸条、发送私信和赠送礼物，余额不足时可在“我的钻石”充值。</text>
					<text class="rule-item"><text class="rule-dot">•</text>收到好友赠送的礼物会增加魅力值，记录每一份被看见的心意。</text>
				</view>
			</view>

			<view class="reward-section level-section">
				<text class="section-title">一起解锁的权益</text>
				<view class="level-row"><text>日常互动</text><text>每日完成浏览、共鸣、发布等任务，持续积累钻石。</text></view>
				<view class="level-row"><text>魅力成长</text><text>收到礼物即可获得对应魅力值，逐步解锁更高魅力等级。</text></view>
				<view class="level-row"><text>会员畅聊</text><text>开通 VIP 后发送私信不消耗钻石，还可领取每日签到 60 钻。</text></view>
				<view class="level-row"><text>会员专享</text><text>会员标识、专属主页装扮、专属礼物和会员钻石礼包。</text></view>
			</view>

			<view class="reward-section invited-section">
				<view class="section-title-row"><text class="section-title">我邀请的好友</text><text class="invite-list-total">{{ inviteCount }} 人</text></view>
				<view class="invite-list">
					<view v-if="loading" class="list-empty">正在加载邀请记录</view>
					<view v-else-if="!invitees.length" class="list-empty">分享给好友后，成功加入的伙伴会出现在这里</view>
					<view v-for="item in invitees" :key="item.id" class="invitee-row">
						<image class="invitee-avatar" :src="item.avatarUrl || defaultAvatarUrl" mode="aspectFill" />
						<view class="invitee-copy"><text class="invitee-name">{{ item.nickname }}</text><text class="invitee-meta">{{ item.city || '刚刚加入' }} · {{ formatTime(item.createdAt) }}</text></view>
						<text class="invitee-reward">+{{ item.rewardDiamonds }} 钻</text>
					</view>
				</view>
			</view>
			<text class="notice">邀请功能用于分享和记录同频相遇。具体钻石任务、会员套餐和礼物价格以页面实时展示为准。</text><view class="bottom-safe" />
		</scroll-view>
	</view>
</template>

<script>
import { getCurrentUser } from '../../utils/auth';
import { createInvitationCode, fetchInvitationSummary } from '../../api/user';
import { DEFAULT_AVATAR_URL } from '../../config';
import { showRequestError } from '../../utils/feedback';

export default {
	data() { return { statusBarHeight: 24, scrollHeight: 600, loading: false, codeLoading: false, invitationCodeUrl: '', inviteCount: 0, rewardDiamonds: 0, rewardPerInvite: 20, invitees: [], inviterId: '', defaultAvatarUrl: DEFAULT_AVATAR_URL }; },
	onLoad() {
		const systemInfo = uni.getSystemInfoSync();
		this.statusBarHeight = Number(systemInfo.statusBarHeight || 24);
		const navigationHeight = Math.round(47 * (Number(systemInfo.windowWidth) || 375) / 375);
		this.scrollHeight = Math.max(320, Number(systemInfo.windowHeight || 700) - this.statusBarHeight - navigationHeight);
		const user = getCurrentUser() || {};
		this.inviterId = String(user.id || user.userId || '');
		this.loadInvitationSummary();
		this.loadInvitationCode();
	},
	onShow() { this.loadInvitationSummary(); },
	methods: {
		goBack() { uni.navigateBack({ fail: () => uni.switchTab({ url: '/pages/meet/index' }) }); },
		getSharePathForAppMessage() {
			const user = getCurrentUser() || {};
			const inviterId = String(user.id || user.userId || this.inviterId || '').trim();
			if (inviterId) this.inviterId = inviterId;
			const inviter = inviterId ? `?inviter=${encodeURIComponent(inviterId)}` : '';
			return `/pages/meet/index${inviter}`;
		},
		async loadInvitationCode() {
			this.codeLoading = true;
			try {
				const result = await createInvitationCode();
				this.invitationCodeUrl = String(result.codeUrl || '');
			} catch (error) {
				this.invitationCodeUrl = '';
			} finally { this.codeLoading = false; }
		},
		previewInvitationCode() {
			if (!this.invitationCodeUrl) return;
			uni.previewImage({ current: this.invitationCodeUrl, urls: [this.invitationCodeUrl] });
		},
		saveInvitationCode() {
			if (!this.invitationCodeUrl) return;
			uni.downloadFile({
				url: this.invitationCodeUrl,
				success: ({ statusCode, tempFilePath }) => {
					if (statusCode !== 200) { uni.showToast({ title: '二维码下载失败', icon: 'none' }); return; }
					uni.saveImageToPhotosAlbum({
						filePath: tempFilePath,
						success: () => uni.showToast({ title: '二维码已保存', icon: 'success' }),
						fail: () => uni.showToast({ title: '请允许保存到相册', icon: 'none' })
					});
				},
				fail: () => uni.showToast({ title: '二维码下载失败', icon: 'none' })
			});
		},
		async loadInvitationSummary() {
			this.loading = true;
			try {
				const summary = await fetchInvitationSummary();
				this.inviterId = String(summary.inviterId || this.inviterId || '').trim();
				this.inviteCount = Number(summary.inviteCount || 0);
				this.rewardDiamonds = Number(summary.rewardDiamonds || 0);
				this.rewardPerInvite = Number(summary.rewardPerInvite || 20);
				this.invitees = Array.isArray(summary.items) ? summary.items : [];
			} catch (error) {
				showRequestError(error, '邀请记录加载失败');
			} finally { this.loading = false; }
		},
		formatTime(value) {
			const date = new Date(value);
			if (Number.isNaN(date.getTime())) return '刚刚';
			return `${date.getMonth() + 1}月${date.getDate()}日`;
		}
	}
};
</script>

<style lang="scss" scoped>
.invite-page { height: 100vh; background: #eefcf7; color: #284c4a; overflow: hidden; }.invite-header { position: relative; z-index: 3; background: #effdf8; }.header-row { display: flex; align-items: center; justify-content: space-between; height: 94rpx; padding: 0 24rpx; box-sizing: border-box; }.back-button, .header-space { width: 64rpx; height: 64rpx; flex-shrink: 0; }.back-button { display: flex; align-items: center; justify-content: center; }.back-button:active { opacity: .55; }.back-arrow { width: 19rpx; height: 19rpx; margin-left: 8rpx; border-left: 3rpx solid #41736d; border-bottom: 3rpx solid #41736d; transform: rotate(45deg); }.header-title { color: #315e59; font-size: 31rpx; font-weight: 700; }.invite-scroll { width: 100%; }
.invite-hero { position: relative; min-height: 336rpx; padding: 28rpx 52rpx 46rpx; overflow: hidden; background: linear-gradient(125deg, #aef5d6 0%, #d7f8ec 46%, #ffe9ed 100%); box-sizing: border-box; }.hero-cloud { position: absolute; border-radius: 50%; background: rgba(255,255,255,.42); }.cloud-one { width: 240rpx; height: 240rpx; top: -136rpx; left: -72rpx; }.cloud-two { width: 190rpx; height: 190rpx; right: -48rpx; bottom: -100rpx; }.hero-title, .hero-copy { position: relative; z-index: 1; display: block; }.hero-title { color: #173f3a; font-size: 45rpx; font-weight: 800; line-height: 1.24; }.hero-title-accent { margin-top: 5rpx; color: #f05e70; }.hero-copy { margin-top: 20rpx; color: #56817b; font-size: 22rpx; }.hero-spark { position: absolute; z-index: 1; color: #ff8e58; font-size: 35rpx; }.spark-one { top: 74rpx; left: 410rpx; transform: rotate(-14deg); }.spark-two { top: 164rpx; left: 476rpx; color: #f58a9d; font-size: 26rpx; }
.gift-stack { position: absolute; z-index: 1; right: 68rpx; top: 62rpx; width: 130rpx; height: 126rpx; transform: rotate(-9deg); }.gift-box { position: absolute; bottom: 0; left: 10rpx; width: 112rpx; height: 78rpx; border-radius: 12rpx; background: #ff826b; box-shadow: 0 16rpx 18rpx rgba(207, 85, 77, .17); }.gift-lid { position: absolute; z-index: 2; bottom: 69rpx; left: 3rpx; width: 126rpx; height: 25rpx; border-radius: 10rpx; background: #ffad4f; }.gift-ribbon { width: 24rpx; height: 100%; margin: auto; background: #fff2a9; }.gift-bow { position: absolute; z-index: 3; top: 12rpx; width: 46rpx; height: 28rpx; border-radius: 50% 50% 45% 45%; background: #fff2a9; }.bow-left { left: 27rpx; transform: rotate(28deg); }.bow-right { right: 25rpx; transform: rotate(-28deg); }
.invite-card { position: relative; z-index: 2; margin: -22rpx 28rpx 0; padding: 30rpx 30rpx 34rpx; border-radius: 18rpx; background: #fff; box-shadow: 0 16rpx 36rpx rgba(61, 129, 110, .1); text-align: center; }.invite-stats { display: flex; align-items: center; justify-content: center; color: #466d68; font-size: 23rpx; }.invite-stats > view { display: flex; flex: 1; flex-direction: column; }.count-value { margin-top: 4rpx; color: #1e4e49; font-size: 42rpx; font-weight: 800; }.diamond-value { color: #d88932; font-size: 34rpx; }.stats-divider { width: 1rpx; height: 64rpx; background: #e2f0eb; }.poster-panel { position: relative; display: flex; align-items: center; justify-content: center; width: 270rpx; height: 270rpx; margin: 18rpx auto 12rpx; overflow: hidden; background: #fff; box-shadow: inset 0 0 0 1rpx #e2f1ec; }.invitation-code { width: 250rpx; height: 250rpx; }.code-state { display: flex; flex-direction: column; align-items: center; gap: 15rpx; color: #7d9c96; font-size: 20rpx; }.code-loading-dot { width: 42rpx; height: 42rpx; border: 5rpx solid #d8eee7; border-top-color: #35bfa8; border-radius: 50%; }.code-error-icon { display: flex; align-items: center; justify-content: center; width: 44rpx; height: 44rpx; border-radius: 50%; background: #fff0ed; color: #e58372; font-size: 28rpx; font-weight: 700; }.save-hint { display: block; color: #71918c; font-size: 20rpx; }.share-button { width: 100%; height: 80rpx; margin-top: 24rpx; border-radius: 40rpx; background: #37cdb6; color: #fff; font-size: 29rpx; line-height: 80rpx; box-shadow: 0 10rpx 18rpx rgba(51, 194, 169, .22); }.share-button::after { border: 0; }.share-button-hover { opacity: .82; }
.reward-section { margin: 36rpx 34rpx 0; }.section-title-row { display: flex; align-items: center; gap: 8rpx; }.section-title { color: #244d48; font-size: 31rpx; font-weight: 800; }.title-gift { font-size: 30rpx; }.rule-list { margin-top: 17rpx; }.rule-item { display: block; margin-top: 14rpx; color: #436964; font-size: 24rpx; line-height: 1.55; }.rule-dot { margin-right: 10rpx; color: #25cfaa; font-size: 35rpx; vertical-align: -2rpx; }.level-section { padding: 25rpx; border-radius: 14rpx; background: rgba(255,255,255,.7); }.level-row { display: flex; gap: 18rpx; padding: 17rpx 0; border-bottom: 1rpx solid #d9eee8; color: #5d7e79; font-size: 22rpx; line-height: 1.42; }.level-row:last-child { border-bottom: 0; padding-bottom: 0; }.level-row text:first-child { width: 112rpx; flex-shrink: 0; color: #287c70; font-weight: 700; }.invited-section { margin-bottom: 0; }.invite-list-total { margin-left: auto; color: #78a49d; font-size: 22rpx; }.invite-list { margin-top: 17rpx; overflow: hidden; border-radius: 14rpx; background: #fff; box-shadow: 0 8rpx 20rpx rgba(55, 112, 98, .06); }.list-empty { padding: 52rpx 26rpx; color: #83a49f; font-size: 22rpx; text-align: center; }.invitee-row { display: flex; align-items: center; gap: 16rpx; min-height: 100rpx; padding: 18rpx 22rpx; box-sizing: border-box; }.invitee-row + .invitee-row { border-top: 1rpx solid #e6f2ee; }.invitee-avatar { width: 60rpx; height: 60rpx; border-radius: 50%; background: #e4f4ef; flex-shrink: 0; }.invitee-copy { display: flex; flex: 1; flex-direction: column; min-width: 0; }.invitee-name { overflow: hidden; color: #365c57; font-size: 25rpx; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }.invitee-meta { margin-top: 7rpx; color: #8ba7a2; font-size: 20rpx; }.invitee-reward { color: #d88932; font-size: 24rpx; font-weight: 700; flex-shrink: 0; }.notice { display: block; margin: 30rpx 36rpx 0; color: #81a29d; font-size: 20rpx; line-height: 1.7; }.bottom-safe { height: calc(40rpx + env(safe-area-inset-bottom)); }
</style>
